-- ============================================================================
-- Relevés produits : « Non renseigné » importé à tort comme « En rupture »
-- ============================================================================
-- Le tableur Google Sheets d'origine (export compact du 10/10/2026) laisse vide
-- BR Délice 15g et BR Delice Pouch 350g dans ~24 000 visites (référence non
-- relevée). L'import les a écrites « En rupture », ce qui fait chuter la
-- disponibilité Délice. Vérifié sur 150 visites tirées au hasard : chaque
-- « Non renseigné » du tableur est « En rupture » en base, toutes les autres
-- valeurs concordent ; les 8 premiers caractères de visite_id sont uniques.
--
-- La correction RETIRE la clé (la référence redevient « non renseignée »),
-- seulement si la base dit exactement « En rupture ».
--
-- Deux temps, car chaque mise à jour de visites.data relance le calcul du
-- Perfect Store (déclencheurs trg_perfect_store et visites_perfect_store) :
--   1. cette migration crée la liste des cellules à corriger (aucune visite
--      modifiée) et la fonction corriger_releves_2026_10(lot) ;
--   2. dans l'éditeur SQL, lancer `select public.corriger_releves_2026_10(500);`
--      jusqu'à ce qu'il renvoie 0 (≈ 50 appels), puis supprimer la table et la
--      fonction (fin du fichier, en commentaire).
--
-- APPLIQUÉE EN PRODUCTION le 10/10/2026 : table et fonction par migration, liste
-- chargée par la clé de service (fichier trop lourd pour l'éditeur), index
-- temporaire sur left(visite_id, 8) pendant l'opération, 99 lots. Résultat :
-- 46 537 cellules retirées (brd_15g 24 252 → 1 074 « En rupture », brd_350g
-- 24 499 → 1 142) ; 2 400 lignes sans effet (visite absente de la base ou valeur
-- déjà différente). Index, fonction et table supprimés ensuite. NE PAS REJOUER.
-- ============================================================================

create table if not exists public._correction_releves_2026_10 (
  prefixe text not null,
  famille text not null,
  sku text not null,
  traite boolean not null default false,
  modifie boolean,
  primary key (prefixe, famille, sku)
);
alter table public._correction_releves_2026_10 enable row level security;
revoke all on public._correction_releves_2026_10 from anon, authenticated;

insert into public._correction_releves_2026_10 (prefixe, famille, sku)
select p, 'imp', 'br_20g' from unnest(array[
    '59191a69'
]) as p
on conflict do nothing;
