create or replace function public.corriger_releves_2026_10(p_lot int default 500)
returns int
language plpgsql
security definer
set search_path = public
as $$
declare
  c record;
  n int;
begin
  for c in
    select prefixe, famille, sku from _correction_releves_2026_10
    where not traite order by prefixe limit p_lot
  loop
    update visites v
       set data = v.data #- array['produits', c.famille, c.sku]
     where left(v.visite_id, 8) = c.prefixe
       and v.data -> 'produits' -> c.famille ->> c.sku = 'En rupture';
    get diagnostics n = row_count;
    update _correction_releves_2026_10 set traite = true, modifie = n > 0
     where prefixe = c.prefixe and famille = c.famille and sku = c.sku;
  end loop;
  return (select count(*) from _correction_releves_2026_10 where not traite);
end $$;
revoke all on function public.corriger_releves_2026_10(int) from public, anon, authenticated;

